HEAD = '''<!doctype html><html lang="ar"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>دليل كتاب الأنشطة · Hiraa</title><style>
@font-face{font-family:TT;src:url("../../../art/fonts/thmanyahseriftext-Regular.woff2");font-weight:400}
@font-face{font-family:TT;src:url("../../../art/fonts/thmanyahseriftext-Bold.woff2");font-weight:700}
@font-face{font-family:TD;src:url("../../../art/fonts/thmanyahserifdisplay-Bold.woff2");font-weight:700}
@page{size:A4;margin:10mm} *{box-sizing:border-box}
body{margin:0;font-family:TT,"DejaVu Sans",serif;direction:rtl;color:#1F2A3C;font-size:13pt;line-height:1.55;background:#E9E3D6}
.page{width:190mm;height:277mm;overflow:hidden;page-break-after:always;position:relative;background:#fff;margin:12px auto;box-shadow:0 2px 12px rgba(0,0,0,.12)}
.fit{padding:6mm}
.hd{border-radius:18px;padding:10px 16px;margin-bottom:8px;color:#fff}
.hd .t{font-family:TD;font-size:21pt;line-height:1.3} .hd .m{font-size:10.5pt;opacity:.95}
.q{border:2px solid #E5DCC8;border-radius:16px;padding:8px 12px;margin:8px 0;break-inside:avoid}
.qt{font-weight:700} .qa{margin-top:5px;background:#F1F8F3;border-radius:10px;padding:5px 10px;font-size:11.5pt}
.tip{background:#FFF8EA;border:2px solid #E3C07A;border-radius:14px;padding:7px 12px;margin-top:8px;font-size:11.5pt}
.nt{font-size:10pt;color:#5B6472;margin-top:8px;border-top:1px dashed #C9BFA8;padding-top:6px}
</style></head><body>'''
TAIL = '''<script>document.fonts.ready.then(function(){var H=277*96/25.4;document.querySelectorAll('.page').forEach(function(p){var f=p.querySelector('.fit');var h=f.scrollHeight;if(h>H){f.style.zoom=(H/h*0.99).toFixed(4);}});});</script></body></html>'''

def esc(s): return html.escape(s, quote=False)

def build(y, l):
    d = A[y][l]; c = COL[y]
    body = '<div class="page"><div class="fit">'
    body += f'<div class="hd" style="background:{c}"><div class="t">دليل كتاب الأنشطة: {esc(d["title"])}</div><div class="m">«أنشطتي في السنع الإماراتي» · الصف {GN[y]} · كتاب الأنشطة {esc(d["page"])}</div></div>'
    for i, (q, a) in enumerate(d['items'], 1):
        body += f'<div class="q"><div class="qt">{i}) {esc(q)}</div>' + (f'<div class="qa">الإجابة / التوجيه: {esc(a)}</div>' if a else '') + '</div>'
    body += f'<div class="tip">💡 فكرة للمعلم: {esc(d["tip"])}</div>'
    n = 'نصوص المطلوب مختصرة من كتاب أنشطة الصف ' + GN[y] + '؛ والإجابات مذكورة حيث يحددها النشاط نفسه. ما يعتمد على صورة فاعرضه من كتب الطلاب ولا تنسخ الصور (فيها الشيخ زايد).'
    if d['note']: n += ' ' + d['note']
    body += f'<div class="nt">{esc(n)}</div></div></div>'
    return HEAD + body + TAIL

if __name__ == '__main__':
    n = 0
    for y in A:
        for l in A[y]:
            out = f'{ROOT}/resources/ssd/SN-Y{y}-T1-{l}'
            os.makedirs(out, exist_ok=True)
            open(out + '/activity-guide.html', 'w', encoding='utf8').write(build(y, l)); n += 1
    print(n, 'guides')
